import {
	Component,
	Event,
	EventEmitter,
	Host,
	Listen,
	Method,
	Prop,
	State,
	VNode,
	h,
} from "@stencil/core";
import { HbrTableNS } from "../../interfaces";
import "../../utils/closestPolifill";
import { isFilterBtn } from "./filter.button";
import { FilterType } from "./filter.service";
import { LogicFunction } from "./filter.types";

/**
 * @typedef FilterItem
 * @type {object}
 * @property {ColumnProp} prop - column id
 * @property {FilterType} type - filter type definition
 * @property {any} value - value for additional filtering, text value or some id
 */
export type FilterItem = {
	prop?: HbrTableNS.ColumnProp;
	type?: FilterType;
	value?: any;
};

export type ShowData = {
	x: number;
	y: number;
} & FilterItem;

const defaultType: FilterType = "contains";

@Component({
	tag: "revogr-filter-panel",
	styleUrl: "filter.style.scss",
})
export class FilterPanel {
	private extraElement: HTMLInputElement | undefined;
	@State() changes: ShowData | undefined;
	@Prop({ mutable: true, reflect: true }) uuid: string;
	@Prop() filterTypes: Record<string, string[]> = {};
	@Prop() revogrid: HTMLHbrTableElement;
	@Prop() filterNames: Record<string, string> = {};
	@Prop() filterEntities: Record<string, LogicFunction> = {};
	@Event() filterChange: EventEmitter<FilterItem>;
	@Listen("mousedown", { target: "document" }) onMouseDown(
		e: MouseEvent,
	): void {
		if (this.changes && !e.defaultPrevented) {
			const el = e.target as HTMLElement;
			if (this.isOutside(el) && !isFilterBtn(el)) {
				this.changes = undefined;
			}
		}
	}
	@Method() async show(newEntity?: ShowData) {
		this.changes = newEntity;
		if (this.changes) {
			this.changes.type = this.changes.type || defaultType;
		}
	}

	@Method() async getChanges() {
		return this.changes;
	}

	renderConditions(type: FilterType) {
		const options: VNode[] = [];
		for (const gIndex in this.filterTypes) {
			options.push(
				<option value={defaultType}>{this.filterNames[defaultType]}</option>,
			);

			options.push(
				...this.filterTypes[gIndex].map((k) => (
					<option value={k} selected={type === k}>
						{this.filterNames[k]}
					</option>
				)),
			);
			options.push(<option disabled />);
		}
		return options;
	}

	renderExtra(extra?: string, value?: any) {
		this.extraElement = undefined;
		if (!this.revogrid?.enableColumnPopSelect || extra === "input") {
			return (
				<input
					type="text"
					value={value}
					onInput={(e) =>
						(this.changes.value = (e.target as HTMLInputElement).value)
					}
					onKeyDown={(e) => this.onKeyDown(e)}
					ref={(e) => (this.extraElement = e)}
				/>
			);
		}
		return "";
	}

	customRenderer(column): VNode | string | void {
		const tpl = column?.columnPopTemplate;
		if (tpl) {
			return tpl(h as unknown as HbrTableNS.HyperFunc<VNode>, column);
		}
	}

	render() {
		if (!this.changes || !this.changes) {
			return <Host style={{ display: "none" }} />;
		}
		const style = {
			display: "block",
			left: `${this.changes.x}px`,
			top: `${this.changes.y}px`,
		};
		let custom = undefined;
		this.revogrid.columns.forEach((c: any) => {
			if (c.prop === this.changes.prop) {
				custom = this.customRenderer(c);
			}
		});
		if (custom) {
			return <Host style={style}>{custom}</Host>;
		}

		return (
			<Host style={style}>
				<label>Column Filter</label>
				{this.revogrid?.enableColumnPopSelect && (
					<select class="select-css" onChange={(e) => this.onFilterChange(e)}>
						{this.renderConditions(this.changes.type)}
					</select>
				)}
				<div>
					{this.renderExtra(
						this.filterEntities[this.changes.type].extra,
						this.changes.value,
					)}
				</div>
				<div class="button-group">
					<hbr-button size="small" variant="fill" onClick={() => this.onSave()}>
						Save
					</hbr-button>
					<hbr-button
						size="small"
						variant="outline"
						onClick={() => this.onCancel()}
					>
						Cancel
					</hbr-button>
				</div>
			</Host>
		);
	}

	private onFilterChange(e: Event) {
		if (!this.changes) {
			throw new Error("Changes required per edit");
		}
		const el = e.target as HTMLSelectElement;
		const type = el.value as FilterType;
		this.changes = {
			...this.changes,
			type,
		};
	}

	private onKeyDown(e: KeyboardEvent) {
		if (e.key.toLowerCase() === "enter") {
			this.onSave();
		}
	}

	private onCancel() {
		this.changes = undefined;
	}

	private onSave() {
		if (!this.changes) {
			throw new Error("Changes required per edit");
		}
		this.filterChange.emit({
			prop: this.changes.prop,
			type: this.changes.type,
			value: this.extraElement?.value?.trim(),
		});
		this.changes = undefined;
	}

	private isOutside(e: HTMLElement | null) {
		if (e.classList.contains(`[uuid="${this.uuid}"]`)) {
			return false;
		}
		return !e?.closest(`[uuid="${this.uuid}"]`);
	}
}
